/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_calc_sales_detail_subtotal_ins` BEFORE INSERT ON `sales_detail` FOR EACH ROW BEGIN
        IF NEW.discount IS NULL THEN
            SET NEW.discount = 0.00;
